/*!
 * Yozora custom source for seanime — Mihon source catalog (keiyoushi)
 *
 * Materializes the Mihon main extension repository index — the JSON index
 * that ends in .json at
 *   https://raw.githubusercontent.com/keiyoushi/extensions/main/index.json
 * (verified live 2026-11: 1.55 MB, 1554 extensions, shape
 *  { name, badgeLabel, signingKey, contact, extensionList: { extensions: [...] } }).
 *
 * This is a CATALOG source: Mihon extensions are Android APKs, which the
 * goja payload runtime cannot execute — so chapters/pages are honestly
 * unavailable. What this source gives Yozora is real, live discovery of
 * every Mihon source: browse all 1554, search by name/package/site,
 * `lang:xx` and `nsfw:true|false` filters, with APK download URL in the
 * entry description.
 *
 * seanime custom-source contract: global `class Provider` with
 * getSettings / listManga / getManga / getMangaDetails.
 */

const INDEX_URL = "https://raw.githubusercontent.com/keiyoushi/extensions/main/index.json"
const SITE = "https://github.com/keiyoushi/extensions"
const BROWSER_UA =
  "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36"

interface MihonSource {
  id: string
  name: string
  language: string
  homeUrl?: string
}
interface MihonEntry {
  name: string
  packageName: string
  resources?: { apkUrl?: string; iconUrl?: string }
  versionName?: string
  contentWarning?: string
  sources?: MihonSource[]
}

/** Module-level cache of the 1.55 MB index (bounded, refreshed on demand). */
let cacheEntries: MihonEntry[] | null = null
let cacheAt = 0
const CACHE_TTL_MS = 30 * 60 * 1000

async function loadIndex(): Promise<MihonEntry[]> {
  const now = Date.now()
  if (cacheEntries && now - cacheAt < CACHE_TTL_MS) return cacheEntries
  let lastErr: unknown = null
  for (let attempt = 0; attempt < 2; attempt++) {
    try {
      const res = await fetch(INDEX_URL, {
        headers: { "User-Agent": BROWSER_UA, Accept: "application/json" },
        timeout: 15000,
      })
      if (res.status >= 400) {
        throw ("mihon-cs: index answered HTTP " + res.status)
      }
      const j = JSON.parse(res.text()) as Record<string, unknown>
      const list = j && j.extensionList ? (j.extensionList as Record<string, unknown>) : null
      const exts = list && list.extensions ? (list.extensions as MihonEntry[]) : null
      if (!exts || !exts.length) throw ("mihon-cs: index contained no extensions")
      cacheEntries = exts
      cacheAt = now
      return exts
    } catch (e) {
      lastErr = e
    }
  }
  throw lastErr
}

/** Stable numeric local id from the packageName (djb2, 40-bit space). */
function hashId(s: string): number {
  let h = 5381
  for (let i = 0; i < s.length; i++) {
    h = ((h << 5) + h + s.charCodeAt(i)) | 0
  }
  return (h >>> 0) % 1099511627775
}

const idRegistry: Record<number, string> = {}
function remember(pkg: string): number {
  const id = hashId(pkg)
  idRegistry[id] = pkg
  return id
}

function isNsfwEntry(e: MihonEntry): boolean {
  return String(e.contentWarning || "") === "CONTENT_WARNING_NSFW"
}

function baseMangaOf(e: MihonEntry): Record<string, unknown> {
  const src = e.sources && e.sources.length ? e.sources[0] : null
  const langs: string[] = []
  if (e.sources) {
    const seen: Record<string, boolean> = {}
    for (let i = 0; i < e.sources.length; i++) {
      const l = String(e.sources[i].language || "all")
      if (!seen[l]) {
        seen[l] = true
        langs.push(l)
      }
    }
  }
  const apk = e.resources && e.resources.apkUrl ? e.resources.apkUrl : ""
  const home = src && src.homeUrl ? src.homeUrl : ""
  const title = e.name || e.packageName
  const lines: string[] = []
  lines.push("Mihon source (keiyoushi index): " + title)
  if (src && src.name) lines.push("Source: " + src.name)
  if (langs.length) lines.push("Languages: " + langs.join(", "))
  if (e.versionName) lines.push("Version: " + e.versionName)
  if (isNsfwEntry(e)) lines.push("18+ (NSFW source)")
  lines.push("Install: install the extension APK in Mihon — " + apk)
  const media: Record<string, unknown> = {
    id: remember(e.packageName),
    idMal: null,
    title: {
      romaji: title,
      english: title,
      native: null,
      userPreferred: title,
    },
    coverImage: {
      extraLarge: e.resources && e.resources.iconUrl ? e.resources.iconUrl : null,
      large: e.resources && e.resources.iconUrl ? e.resources.iconUrl : null,
      medium: e.resources && e.resources.iconUrl ? e.resources.iconUrl : null,
      color: null,
    },
    bannerImage: null,
    // Catalog entries are not readable galleries — single "MANGA" entry
    // carries the metadata; chapters stay null (honest).
    format: "MANGA",
    status: "FINISHED",
    description: lines.join("\n"),
    genres: ["Mihon"].concat(langs.slice(0, 4)).concat(isNsfwEntry(e) ? ["NSFW"] : []),
    isAdult: isNsfwEntry(e),
    chapters: null,
    volumes: null,
    seasonYear: null,
    averageScore: null,
    popularity: null,
    countryOfOrigin: null,
    siteUrl: home || apk || SITE,
    staff: { edges: [] },
    nextAiringEpisode: null,
    startDate: null,
    endDate: null,
  }
  return media
}

function matches(e: MihonEntry, query: string): boolean {
  const q = query.toLowerCase()
  if (q.indexOf("lang:") === 0) {
    const want = q.slice(5).trim()
    if (e.sources) {
      for (let i = 0; i < e.sources.length; i++) {
        if (String(e.sources[i].language || "all").toLowerCase() === want) return true
      }
    }
    return false
  }
  if (q.indexOf("nsfw:") === 0) {
    const want = q.slice(5).trim() === "true" || q.slice(5).trim() === "yes" || q.slice(5).trim() === "1"
    return isNsfwEntry(e) === want
  }
  // free-text across name, package and source name / site host
  const hay = [e.name, e.packageName, e.sources && e.sources.length ? e.sources[0].name : "", e.sources && e.sources.length && e.sources[0].homeUrl ? e.sources[0].homeUrl : ""]
    .join(" ")
    .toLowerCase()
  return hay.indexOf(q) >= 0
}

class Provider {
  async getSettings(): Promise<Record<string, boolean>> {
    return { supportsAnime: false, supportsManga: true }
  }

  async listManga(search: string, page: number, perPage: number): Promise<Record<string, unknown>> {
    const p = Math.max(1, page || 1)
    const per = Math.min(48, Math.max(12, perPage || 24))
    const entries = await loadIndex()
    const q = (search || "").trim()
    let filtered: MihonEntry[] = entries
    if (q) {
      filtered = []
      for (let i = 0; i < entries.length; i++) {
        if (matches(entries[i], q)) filtered.push(entries[i])
      }
    }
    if (!filtered.length) {
      throw ("mihon-cs: no Mihon sources match '" + q + "' — try a site name, language (lang:en), or nsfw:true")
    }
    // NSFW sources last on unfiltered browse so the default feed stays tame.
    if (!q) {
      const tame: MihonEntry[] = []
      const adult: MihonEntry[] = []
      for (let i = 0; i < filtered.length; i++) {
        if (isNsfwEntry(filtered[i])) adult.push(filtered[i])
        else tame.push(filtered[i])
      }
      filtered = tame.concat(adult)
    }
    const total = filtered.length
    const totalPages = Math.max(1, Math.ceil(total / per))
    const start = (p - 1) * per
    const slice = filtered.slice(start, start + per)
    if (!slice.length) {
      throw ("mihon-cs: page " + p + " is beyond the catalog (" + totalPages + " pages)")
    }
    const media: Record<string, unknown>[] = []
    for (let i = 0; i < slice.length; i++) media.push(baseMangaOf(slice[i]))
    return { media: media, page: p, totalPages: totalPages, total: total }
  }

  async getManga(ids: number[]): Promise<Record<string, unknown>[]> {
    const entries = await loadIndex()
    const byPkg: Record<string, MihonEntry> = {}
    for (let i = 0; i < entries.length; i++) byPkg[entries[i].packageName] = entries[i]
    const out: Record<string, unknown>[] = []
    for (let i = 0; i < ids.length; i++) {
      const pkg = idRegistry[ids[i]]
      if (pkg && byPkg[pkg]) out.push(baseMangaOf(byPkg[pkg]))
    }
    return out
  }

  async getMangaDetails(id: number): Promise<Record<string, unknown> | null> {
    const list = await this.getManga([id])
    return list.length > 0 ? list[0] : null
  }

  async listAnime(search: string, page: number, perPage: number): Promise<Record<string, unknown>> {
    throw ("mihon-cs is a manga source catalog (honest refusal)")
  }

  async getAnime(ids: number[]): Promise<Record<string, unknown>[]> {
    throw ("mihon-cs is a manga source catalog (honest refusal)")
  }

  async getAnimeDetails(id: number): Promise<null> {
    throw ("mihon-cs is a manga source catalog (honest refusal)")
  }

  async getAnimeWithRelations(id: number): Promise<null> {
    throw ("mihon-cs is a manga source catalog (honest refusal)")
  }

  async getAnimeMetadata(id: number): Promise<null> {
    throw ("mihon-cs is a manga source catalog (honest refusal)")
  }
}
